BEGIN;
CREATE SCHEMA erp_membership_private;
REVOKE ALL ON SCHEMA erp_membership_private FROM PUBLIC,anon,authenticated,service_role;
CREATE UNIQUE INDEX erp_membership_draft_tenant ON public.bf_invoice_drafts(cafe_id,id);
CREATE TABLE public.erp_membership_settings(cafe_id uuid PRIMARY KEY REFERENCES public.cafes(id),revision integer NOT NULL DEFAULT 1,payload jsonb NOT NULL);
CREATE TABLE public.erp_memberships(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid NOT NULL,number bigint GENERATED BY DEFAULT AS IDENTITY,customer_id uuid NOT NULL,package_id uuid NOT NULL,joined_on date NOT NULL,description text NOT NULL DEFAULT '' CHECK(length(description)<=4000),suspended boolean NOT NULL DEFAULT false,deleted boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES auth.users(id),PRIMARY KEY(cafe_id,id),FOREIGN KEY(cafe_id,customer_id) REFERENCES public.bf_parties(cafe_id,id),FOREIGN KEY(cafe_id,package_id) REFERENCES public.erp_credit_packages(cafe_id,id));
CREATE TABLE public.erp_membership_renewals(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid NOT NULL,number bigint GENERATED BY DEFAULT AS IDENTITY,membership_id uuid,customer_id uuid NOT NULL,package_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('membership','credit')),package_snapshot jsonb NOT NULL,invoice_date date NOT NULL,draft_id uuid,invoice_id uuid,invoice_total numeric(16,2) NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','paid','refunded')),starts_on date,ends_on date,activated_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_by uuid NOT NULL REFERENCES auth.users(id),PRIMARY KEY(cafe_id,id),FOREIGN KEY(cafe_id,membership_id) REFERENCES public.erp_memberships(cafe_id,id),FOREIGN KEY(cafe_id,customer_id) REFERENCES public.bf_parties(cafe_id,id),FOREIGN KEY(cafe_id,package_id) REFERENCES public.erp_credit_packages(cafe_id,id),FOREIGN KEY(cafe_id,draft_id) REFERENCES public.bf_invoice_drafts(cafe_id,id),FOREIGN KEY(cafe_id,invoice_id) REFERENCES public.bf_documents(cafe_id,id),UNIQUE(cafe_id,draft_id),UNIQUE(cafe_id,invoice_id));
CREATE TABLE public.erp_membership_freezes(cafe_id uuid NOT NULL,id uuid NOT NULL,membership_id uuid NOT NULL,renewal_id uuid NOT NULL,starts_on date NOT NULL,ends_on date NOT NULL CHECK(ends_on>=starts_on),extend_membership boolean NOT NULL,extend_credits boolean NOT NULL,voided boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(cafe_id,id),FOREIGN KEY(cafe_id,membership_id) REFERENCES public.erp_memberships(cafe_id,id),FOREIGN KEY(cafe_id,renewal_id) REFERENCES public.erp_membership_renewals(cafe_id,id));
CREATE TABLE public.erp_membership_events(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid PRIMARY KEY DEFAULT gen_random_uuid(),membership_id uuid,record_id uuid NOT NULL,action text NOT NULL,actor uuid REFERENCES auth.users(id),at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.erp_customer_attendance(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid NOT NULL,number bigint GENERATED BY DEFAULT AS IDENTITY,customer_id uuid NOT NULL,attended_at timestamptz NOT NULL DEFAULT clock_timestamp(),actor uuid NOT NULL REFERENCES auth.users(id),voided boolean NOT NULL DEFAULT false,PRIMARY KEY(cafe_id,id),FOREIGN KEY(cafe_id,customer_id) REFERENCES public.bf_parties(cafe_id,id));
CREATE TABLE erp_membership_private.requests(cafe_id uuid NOT NULL,request_id uuid NOT NULL,actor uuid NOT NULL,action text NOT NULL,input jsonb NOT NULL,result jsonb NOT NULL,PRIMARY KEY(cafe_id,request_id));
CREATE INDEX ON public.erp_memberships(cafe_id,customer_id);
CREATE INDEX ON public.erp_membership_renewals(cafe_id,membership_id,created_at);
CREATE INDEX ON public.erp_membership_freezes(cafe_id,membership_id,starts_on,ends_on);
CREATE INDEX ON public.erp_customer_attendance(cafe_id,attended_at);
CREATE INDEX ON public.erp_membership_events(cafe_id,membership_id,at);
CREATE UNIQUE INDEX erp_credit_source_charge ON public.erp_credit_charges(cafe_id,source_kind,source_id,type_id) WHERE source_id IS NOT NULL;
DO $$DECLARE domains text[];d text;BEGIN domains:=erp_access_private.domains();FOREACH d IN ARRAY ARRAY['memberships','customer_attendance'] LOOP IF NOT(d=ANY(domains)) THEN domains:=domains||d;END IF;UPDATE public.erp_roles SET permissions=permissions||jsonb_build_object(d,jsonb_build_object('read',false,'create',false,'update',false,'delete',false,'approve',false,'settings',false,'files',false)) WHERE NOT(permissions?d);END LOOP;EXECUTE format('CREATE OR REPLACE FUNCTION erp_access_private.domains() RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path='''' AS $f$SELECT %L::text[]$f$',domains);END $$;
CREATE FUNCTION erp_membership_private.authorize(c uuid,a text DEFAULT 'read',d text DEFAULT 'memberships') RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r text;BEGIN r:=brand_finance_private.role_for(c);IF coalesce(r,'') NOT IN('owner','manager','accountant','auditor') OR(a<>'read' AND r='auditor') OR(a='settings' AND r<>'owner') THEN RAISE EXCEPTION 'لا تملك صلاحية إدارة العضويات والحضور' USING ERRCODE='42501';END IF;PERFORM erp_access_private.assert_allowed(c,d,a);RETURN r;END $$;
CREATE FUNCTION erp_membership_private.policy(c uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT jsonb_build_object('revision',coalesce(s.revision,0),'graceDays',0,'attendance','all','invoiceStatus','draft','warehouseId','','issuer',jsonb_build_object('name','','address','','vatNumber',''))||coalesce(s.payload,'{}'::jsonb) FROM(SELECT 1) q LEFT JOIN public.erp_membership_settings s ON s.cafe_id=c$$;
CREATE FUNCTION erp_membership_private.end_date(c uuid,r uuid,credits boolean DEFAULT false) RETURNS date LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT x.ends_on+coalesce((SELECT sum(f.ends_on-f.starts_on+1)::integer FROM public.erp_membership_freezes f WHERE f.cafe_id=c AND f.renewal_id=r AND NOT f.voided AND CASE WHEN credits THEN f.extend_credits ELSE f.extend_membership END),0) FROM public.erp_membership_renewals x WHERE x.cafe_id=c AND x.id=r$$;
CREATE FUNCTION erp_membership_private.sync(c uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.erp_membership_renewals;doc public.bf_documents;state jsonb;paid boolean;new_status text;start_date date;end_date date;line jsonb;member public.erp_memberships;frozen boolean;today date:=(now() AT TIME ZONE 'Asia/Riyadh')::date;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(c::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(c::text,67951));
 FOR r IN SELECT * FROM public.erp_membership_renewals WHERE cafe_id=c ORDER BY created_at,id FOR UPDATE LOOP
  IF r.invoice_id IS NULL AND r.draft_id IS NOT NULL THEN SELECT document_id INTO r.invoice_id FROM public.bf_company_invoices WHERE cafe_id=c AND draft_id=r.draft_id;IF r.invoice_id IS NOT NULL THEN UPDATE public.erp_membership_renewals SET invoice_id=r.invoice_id WHERE cafe_id=c AND id=r.id;END IF;END IF;
  doc:=NULL;state:=NULL;IF r.invoice_id IS NOT NULL THEN SELECT * INTO doc FROM public.bf_documents WHERE cafe_id=c AND id=r.invoice_id;state:=brand_finance_private.document_state(c,r.invoice_id);END IF;
  paid:=CASE WHEN(r.package_snapshot->>'price')::numeric=0 THEN true ELSE doc.id IS NOT NULL AND doc.party_id=r.customer_id AND doc.kind='sale' AND doc.total=r.invoice_total AND coalesce((state->>'outstanding')::numeric,1)<=0 AND coalesce((state->>'refunded_total')::numeric,0)=0 END;
  new_status:=CASE WHEN paid THEN 'paid' WHEN r.activated_at IS NOT NULL OR coalesce((state->>'refunded_total')::numeric,0)>0 THEN 'refunded' ELSE 'pending' END;
  IF paid AND r.activated_at IS NULL THEN
   member:=NULL;IF r.membership_id IS NOT NULL THEN SELECT * INTO member FROM public.erp_memberships WHERE cafe_id=c AND id=r.membership_id;END IF;
   start_date:=CASE WHEN r.membership_id IS NULL THEN r.invoice_date ELSE greatest(member.joined_on,coalesce((SELECT max(erp_membership_private.end_date(c,id))+1 FROM public.erp_membership_renewals WHERE cafe_id=c AND membership_id=r.membership_id AND activated_at IS NOT NULL AND status='paid'),member.joined_on)) END;
   end_date:=(start_date+CASE r.package_snapshot->>'periodUnit' WHEN 'day' THEN make_interval(days=>(r.package_snapshot->>'period')::integer) WHEN 'week' THEN make_interval(days=>7*(r.package_snapshot->>'period')::integer) WHEN 'month' THEN make_interval(months=>(r.package_snapshot->>'period')::integer) ELSE make_interval(years=>(r.package_snapshot->>'period')::integer) END)::date-1;
   UPDATE public.erp_membership_renewals SET starts_on=start_date,ends_on=end_date,activated_at=clock_timestamp() WHERE cafe_id=c AND id=r.id;r.starts_on:=start_date;r.ends_on:=end_date;r.activated_at:=clock_timestamp();
   FOR line IN SELECT value FROM jsonb_array_elements(r.package_snapshot->'lines') LOOP
    INSERT INTO public.erp_credit_charges(cafe_id,id,customer_id,type_id,quantity,starts_on,expires_on,description,suspended,source_kind,source_id,created_by) VALUES(c,gen_random_uuid(),r.customer_id,(line->>'typeId')::uuid,(line->>'quantity')::numeric,start_date,end_date,'اشتراك '||r.number,false,'membership_renewal',r.id,r.created_by);
   END LOOP;
   INSERT INTO public.erp_membership_events(cafe_id,membership_id,record_id,action,actor) VALUES(c,r.membership_id,r.id,'paid_activation',auth.uid());
  END IF;
  IF r.status<>new_status THEN UPDATE public.erp_membership_renewals SET status=new_status WHERE cafe_id=c AND id=r.id;IF r.membership_id IS NOT NULL THEN UPDATE public.erp_memberships SET revision=revision+1 WHERE cafe_id=c AND id=r.membership_id;END IF;END IF;
  frozen:=r.membership_id IS NOT NULL AND(EXISTS(SELECT 1 FROM public.erp_memberships WHERE cafe_id=c AND id=r.membership_id AND(suspended OR deleted)) OR EXISTS(SELECT 1 FROM public.erp_membership_freezes WHERE cafe_id=c AND membership_id=r.membership_id AND NOT voided AND today BETWEEN starts_on AND ends_on));
  UPDATE public.erp_credit_charges SET suspended=NOT paid OR frozen,expires_on=erp_membership_private.end_date(c,r.id,true) WHERE cafe_id=c AND source_kind='membership_renewal' AND source_id=r.id AND(suspended IS DISTINCT FROM(NOT paid OR frozen) OR expires_on IS DISTINCT FROM erp_membership_private.end_date(c,r.id,true));
 END LOOP;
END $$;
CREATE FUNCTION erp_membership_private.status(c uuid,m uuid,on_date date DEFAULT (now() AT TIME ZONE 'Asia/Riyadh')::date) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE row public.erp_memberships;BEGIN
 SELECT * INTO row FROM public.erp_memberships WHERE cafe_id=c AND id=m;IF row.id IS NULL OR row.deleted OR row.suspended THEN RETURN 'suspended';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_membership_freezes WHERE cafe_id=c AND membership_id=m AND NOT voided AND on_date BETWEEN starts_on AND ends_on) THEN RETURN 'frozen';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_membership_renewals WHERE cafe_id=c AND membership_id=m AND status='paid' AND starts_on<=on_date AND erp_membership_private.end_date(c,id)+(erp_membership_private.policy(c)->>'graceDays')::integer>=on_date) THEN RETURN 'active';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_membership_renewals WHERE cafe_id=c AND membership_id=m AND status='paid' AND starts_on>on_date) THEN RETURN 'scheduled';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_membership_renewals WHERE cafe_id=c AND membership_id=m AND status='paid' AND ends_on<on_date) THEN RETURN 'expired';END IF;RETURN 'pending';END $$;
CREATE FUNCTION erp_membership_private.attendance_allowed(c uuid,customer uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=c AND id=customer AND kind='customer' AND active) AND CASE erp_membership_private.policy(c)->>'attendance' WHEN 'all' THEN true WHEN 'members' THEN EXISTS(SELECT 1 FROM public.erp_memberships WHERE cafe_id=c AND customer_id=customer AND NOT deleted) ELSE EXISTS(SELECT 1 FROM public.erp_memberships WHERE cafe_id=c AND customer_id=customer AND NOT deleted AND erp_membership_private.status(c,id)='active') END$$;
CREATE FUNCTION erp_membership_private.charge_allowed(c uuid,charge uuid,d date) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT NOT EXISTS(SELECT 1 FROM public.erp_credit_charges ch JOIN public.erp_membership_renewals r ON r.cafe_id=ch.cafe_id AND r.id=ch.source_id LEFT JOIN public.erp_memberships m ON m.cafe_id=r.cafe_id AND m.id=r.membership_id WHERE ch.cafe_id=c AND ch.id=charge AND ch.source_kind='membership_renewal' AND(r.status<>'paid' OR coalesce(m.suspended OR m.deleted,false) OR EXISTS(SELECT 1 FROM public.erp_membership_freezes f WHERE f.cafe_id=c AND f.membership_id=m.id AND NOT f.voided AND d BETWEEN f.starts_on AND f.ends_on)))$$;
CREATE FUNCTION erp_membership_private.package(c uuid,p uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT(to_jsonb(x)-'cafe_id'-'period_unit')||jsonb_build_object('periodUnit',period_unit,'lines',coalesce((SELECT jsonb_agg(jsonb_build_object('typeId',type_id,'quantity',quantity) ORDER BY position) FROM public.erp_credit_package_lines WHERE cafe_id=c AND package_id=p),'[]'::jsonb)) FROM public.erp_credit_packages x WHERE cafe_id=c AND id=p$$;
CREATE FUNCTION erp_membership_private.create_renewal(c uuid,m uuid,customer uuid,package uuid,invoice_date date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
#variable_conflict use_variable
DECLARE id uuid:=gen_random_uuid();draft uuid:=gen_random_uuid();snapshot jsonb;cfg jsonb;tax numeric;prefs jsonb;payload jsonb;r jsonb;total numeric;source uuid;source_cfg jsonb;
BEGIN
 snapshot:=erp_membership_private.package(c,package);cfg:=erp_membership_private.policy(c);IF snapshot IS NULL OR NOT(snapshot->>'active')::boolean OR(m IS NOT NULL AND snapshot->>'kind'<>'membership') OR(m IS NULL AND snapshot->>'kind'<>'credit') THEN RAISE EXCEPTION 'الباقة غير متاحة لهذا الاشتراك';END IF;
 IF invoice_date IS NULL OR NOT isfinite(invoice_date) OR invoice_date>(now() AT TIME ZONE 'Asia/Riyadh')::date THEN RAISE EXCEPTION 'اختر تاريخ فاتورة صالحًا';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_credit_package_lines l JOIN public.erp_credit_types t ON t.cafe_id=l.cafe_id AND t.id=l.type_id WHERE l.cafe_id=c AND l.package_id=package AND NOT t.active) THEN RAISE EXCEPTION 'تحتوي الباقة على نوع رصيد غير نشط';END IF;
 prefs:=brand_finance_private.invoice_settings(c);tax:=CASE prefs#>>'{advanced,taxMode}' WHEN 'none' THEN 0 WHEN 'specific' THEN(prefs#>>'{advanced,specificTaxRate}')::numeric ELSE 15 END;total:=(snapshot->>'price')::numeric+round((snapshot->>'price')::numeric*tax/100,2);
 IF total=0 THEN draft:=NULL;ELSE
 payload:=jsonb_build_object('invoice',jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('key',1,'productId','','quantity',1,'price',(snapshot->>'price')::numeric,'name',snapshot->>'name','kind','service','vatRate',tax,'taxCategory',CASE WHEN tax=0 THEN 'O' ELSE 'S' END,'exemptionReason',CASE WHEN tax=0 THEN 'خدمة غير خاضعة للضريبة وفق إعدادات الفواتير' ELSE '' END)),'partyId',customer,'warehouseId',cfg->>'warehouseId','accountId','','paymentKind','credit','discountValue',0,'discountKind','amount','taxInclusive',false,'currency','SAR','exchangeRate',1,'note','اشتراك باقة '||(snapshot->>'name')),'issuer',cfg->'issuer','supplyDate',invoice_date,'template','standard','deliveryMethod','print','deposit',jsonb_build_object('kind','amount','value',0,'paid',false),'shipping','none','delivery',jsonb_build_object('confirmed',false,'date',''),'attachments','[]'::jsonb,'extraFields','[]'::jsonb);
 r:=public.brand_finance_save_invoice_draft(c,draft,0,payload);
 END IF;
 INSERT INTO public.erp_membership_renewals(cafe_id,id,membership_id,customer_id,package_id,kind,package_snapshot,invoice_date,draft_id,invoice_total,created_by) VALUES(c,id,m,customer,package,snapshot->>'kind',snapshot,invoice_date,draft,total,auth.uid());
 IF draft IS NOT NULL AND cfg->>'invoiceStatus'='issued' THEN
  source_cfg:=brand_finance_private.order_source_settings(c);SELECT(x->>'id')::uuid INTO source FROM jsonb_array_elements(source_cfg->'sources') x WHERE(x->>'active')::boolean ORDER BY(x->>'id') LIMIT 1;
  IF source IS NOT NULL THEN PERFORM public.brand_finance_set_invoice_order_source(c,draft,(r->>'revision')::integer,source,0);END IF;
  r:=public.brand_finance_issue_company_invoice(c,draft,(r->>'revision')::integer,total);
 END IF;
 PERFORM erp_membership_private.sync(c);RETURN jsonb_build_object('id',coalesce(m,id),'renewalId',id,'draftId',draft,'invoiceId',(SELECT invoice_id FROM public.erp_membership_renewals WHERE cafe_id=c AND erp_membership_renewals.id=id));
END $$;
CREATE FUNCTION erp_membership_private.invoice_link() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r public.erp_membership_renewals;d public.bf_documents;BEGIN
 SELECT * INTO r FROM public.erp_membership_renewals WHERE cafe_id=NEW.cafe_id AND draft_id=NEW.draft_id FOR UPDATE;IF NOT FOUND THEN RETURN NEW;END IF;
 SELECT * INTO d FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.document_id;IF d.party_id<>r.customer_id OR d.kind<>'sale' OR d.total<>r.invoice_total OR coalesce(NEW.snapshot->>'currency','SAR')<>'SAR' THEN RAISE EXCEPTION 'عميل أو إجمالي فاتورة الاشتراك لا يطابق الباقة' USING ERRCODE='22023';END IF;
 UPDATE public.erp_membership_renewals SET invoice_id=NEW.document_id WHERE cafe_id=NEW.cafe_id AND id=r.id;RETURN NEW;END $$;
CREATE TRIGGER erp_membership_invoice_link BEFORE INSERT ON public.bf_company_invoices FOR EACH ROW EXECUTE FUNCTION erp_membership_private.invoice_link();
CREATE FUNCTION erp_membership_private.finance_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE c uuid;row_data jsonb;source uuid;reference uuid;BEGIN row_data:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;c:=(row_data->>'cafe_id')::uuid;source:=coalesce(row_data->>'source_id',row_data->>'document_id',row_data->>'id')::uuid;reference:=nullif(row_data->>'reference_id','')::uuid;IF EXISTS(SELECT 1 FROM public.erp_membership_renewals r WHERE r.cafe_id=c AND(r.invoice_id IN(source,reference) OR EXISTS(SELECT 1 FROM public.bf_documents d WHERE d.cafe_id=c AND d.id=source AND d.reference_id=r.invoice_id))) THEN PERFORM erp_membership_private.sync(c);END IF;RETURN coalesce(NEW,OLD);END $$;
CREATE CONSTRAINT TRIGGER erp_membership_finance_changed AFTER INSERT OR UPDATE OR DELETE ON public.bf_documents DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION erp_membership_private.finance_changed();
DO $$BEGIN IF to_regclass('public.bf_invoice_payments') IS NOT NULL THEN EXECUTE 'CREATE CONSTRAINT TRIGGER erp_membership_payment_changed AFTER INSERT OR UPDATE OR DELETE ON public.bf_invoice_payments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION erp_membership_private.finance_changed()';END IF;END $$;
CREATE FUNCTION erp_membership_private.renewals_json(c uuid,k text DEFAULT 'membership') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.id,'number',r.number,'membershipId',r.membership_id,'customerId',r.customer_id,'packageId',r.package_id,'packageName',r.package_snapshot->>'name','kind',r.kind,'price',r.package_snapshot->'price','period',r.package_snapshot->'period','periodUnit',r.package_snapshot->>'periodUnit','invoiceDate',r.invoice_date,'draftId',r.draft_id,'invoiceId',r.invoice_id,'invoiceNumber',coalesce(e.display_number,d.number::text),'invoiceTotal',r.invoice_total,'outstanding',coalesce((brand_finance_private.document_state(c,r.invoice_id)->>'outstanding')::numeric,r.invoice_total),'status',r.status,'startsOn',r.starts_on,'endsOn',erp_membership_private.end_date(c,r.id),'createdAt',r.created_at) ORDER BY r.created_at DESC),'[]'::jsonb) FROM public.erp_membership_renewals r LEFT JOIN public.bf_documents d ON d.cafe_id=r.cafe_id AND d.id=r.invoice_id LEFT JOIN public.bf_invoice_extensions e ON e.cafe_id=r.cafe_id AND e.document_id=r.invoice_id WHERE r.cafe_id=c AND r.kind=k$$;
CREATE FUNCTION public.erp_memberships_read(p_cafe uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE role text;BEGIN role:=erp_membership_private.authorize(p_cafe);PERFORM erp_membership_private.sync(p_cafe);RETURN jsonb_build_object(
 'memberships',coalesce((SELECT jsonb_agg(jsonb_build_object('id',m.id,'number',number,'revision',revision,'customerId',customer_id,'packageId',coalesce((SELECT r.package_id FROM public.erp_membership_renewals r WHERE r.cafe_id=p_cafe AND r.membership_id=m.id AND r.status='paid' ORDER BY r.starts_on DESC LIMIT 1),package_id),'joinedOn',joined_on,'endsOn',(SELECT max(erp_membership_private.end_date(p_cafe,r.id)) FROM public.erp_membership_renewals r WHERE r.cafe_id=p_cafe AND r.membership_id=m.id AND r.status='paid'),'description',description,'suspended',suspended,'status',erp_membership_private.status(p_cafe,m.id),'createdAt',created_at) ORDER BY number DESC) FROM public.erp_memberships m WHERE cafe_id=p_cafe AND NOT deleted),'[]'::jsonb),
 'renewals',erp_membership_private.renewals_json(p_cafe),
 'freezes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'revision',revision,'membershipId',membership_id,'renewalId',renewal_id,'startsOn',starts_on,'endsOn',ends_on,'extendMembership',extend_membership,'extendCredits',extend_credits,'voided',voided) ORDER BY starts_on DESC) FROM public.erp_membership_freezes WHERE cafe_id=p_cafe),'[]'::jsonb),
 'packages',coalesce((SELECT jsonb_agg(erp_membership_private.package(p_cafe,id) ORDER BY name) FROM public.erp_credit_packages WHERE cafe_id=p_cafe AND kind='membership'),'[]'::jsonb),
 'charges',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'revision',x.revision,'number',x.number,'customerId',x.customer_id,'typeId',x.type_id,'quantity',x.quantity,'startsOn',x.starts_on,'expiresOn',coalesce(x.expires_on::text,''),'description',x.description,'suspended',x.suspended,'sourceKind',x.source_kind,'sourceId',x.source_id,'createdAt',x.created_at,'remaining',erp_credit_private.remaining(p_cafe,x.id))) FROM public.erp_credit_charges x JOIN public.erp_membership_renewals r ON r.cafe_id=x.cafe_id AND r.id=x.source_id WHERE x.cafe_id=p_cafe AND x.source_kind='membership_renewal' AND r.kind='membership'),'[]'::jsonb),
 'creditTypes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'unit',unit)) FROM public.erp_credit_types WHERE cafe_id=p_cafe),'[]'::jsonb),
 'customers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'phone',phone,'active',active) ORDER BY name) FROM public.bf_parties WHERE cafe_id=p_cafe AND kind='customer'),'[]'::jsonb),
 'warehouses',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.bf_warehouses WHERE cafe_id=p_cafe AND active),'[]'::jsonb),'policy',erp_membership_private.policy(p_cafe),
 'events',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'membershipId',membership_id,'recordId',record_id,'action',action,'at',at) ORDER BY at DESC) FROM public.erp_membership_events WHERE cafe_id=p_cafe),'[]'::jsonb),
 'canCreate',role<>'auditor' AND erp_access_private.allowed(p_cafe,'memberships','create'),'canUpdate',role<>'auditor' AND erp_access_private.allowed(p_cafe,'memberships','update'),'canDelete',role<>'auditor' AND erp_access_private.allowed(p_cafe,'memberships','delete'),'canSettings',role='owner' AND erp_access_private.allowed(p_cafe,'memberships','settings'),'today',(now() AT TIME ZONE 'Asia/Riyadh')::date);
END $$;
CREATE FUNCTION public.erp_memberships_write(p_cafe uuid,p_action text,p_input jsonb,p_request uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE i uuid;rev integer;m public.erp_memberships;f public.erp_membership_freezes;r public.erp_membership_renewals;prior erp_membership_private.requests;result jsonb;mid uuid;start_date date;end_date date;current_rev integer;settings jsonb;
BEGIN
 IF p_action NOT IN('create','edit','renew','freeze','freeze_delete','suspend','resume','delete','policy') OR p_request IS NULL OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>20000 THEN RAISE EXCEPTION 'الإجراء غير صالح';END IF;
 PERFORM erp_membership_private.authorize(p_cafe,CASE WHEN p_action='policy' THEN 'settings' WHEN p_action IN('delete','freeze_delete') THEN 'delete' WHEN p_action IN('create','renew','freeze') THEN 'create' ELSE 'update' END);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,67951));PERFORM erp_membership_private.sync(p_cafe);
 SELECT * INTO prior FROM erp_membership_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;IF FOUND THEN IF prior.actor<>auth.uid() OR prior.action<>p_action OR prior.input<>p_input THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات أخرى';END IF;RETURN prior.result;END IF;
 i:=nullif(p_input->>'id','')::uuid;rev:=(p_input->>'revision')::integer;IF rev IS NULL OR rev<0 OR(p_action<>'policy' AND i IS NULL) THEN RAISE EXCEPTION 'راجع معرف السجل وإصداره';END IF;
 IF p_action='policy' THEN
  SELECT revision INTO current_rev FROM public.erp_membership_settings WHERE cafe_id=p_cafe;IF coalesce(current_rev,0)<>rev THEN RAISE EXCEPTION 'تغيرت إعدادات العضويات' USING ERRCODE='40001';END IF;
  IF(p_input->>'graceDays')::integer NOT BETWEEN 0 AND 365 OR p_input->>'graceDays' IS NULL OR coalesce(p_input->>'attendance','') NOT IN('all','members','active') OR coalesce(p_input->>'invoiceStatus','') NOT IN('draft','issued') OR length(coalesce(p_input#>>'{issuer,name}',''))>160 OR length(coalesce(p_input#>>'{issuer,address}',''))>500 OR length(coalesce(p_input#>>'{issuer,vatNumber}',''))>15 THEN RAISE EXCEPTION 'راجع سياسة العضويات';END IF;
  IF nullif(p_input->>'warehouseId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=p_cafe AND id=(p_input->>'warehouseId')::uuid AND active) THEN RAISE EXCEPTION 'المستودع غير متاح';END IF;
  IF p_input->>'invoiceStatus'='issued' AND(nullif(p_input->>'warehouseId','') IS NULL OR length(coalesce(p_input#>>'{issuer,name}',''))<2 OR length(coalesce(p_input#>>'{issuer,address}',''))<8 OR coalesce(p_input#>>'{issuer,vatNumber}','')!~'^3[0-9]{13}3$') THEN RAISE EXCEPTION 'أكمل بيانات البائع والمستودع للإصدار التلقائي';END IF;
  INSERT INTO public.erp_membership_settings VALUES(p_cafe,rev+1,p_input-'revision') ON CONFLICT(cafe_id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload;result:=jsonb_build_object('id',p_cafe);mid:=NULL;i:=p_cafe;
 ELSIF p_action='create' THEN
  IF rev<>0 OR EXISTS(SELECT 1 FROM public.erp_memberships WHERE cafe_id=p_cafe AND id=i) THEN RAISE EXCEPTION 'العضوية موجودة بالفعل' USING ERRCODE='40001';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe AND id=(p_input->>'customerId')::uuid AND kind='customer' AND active) THEN RAISE EXCEPTION 'العميل غير متاح';END IF;
  start_date:=(p_input->>'joinedOn')::date;IF start_date IS NULL OR NOT isfinite(start_date) THEN RAISE EXCEPTION 'راجع تاريخ الالتحاق';END IF;
  INSERT INTO public.erp_memberships(cafe_id,id,customer_id,package_id,joined_on,description,created_by) VALUES(p_cafe,i,(p_input->>'customerId')::uuid,(p_input->>'packageId')::uuid,start_date,coalesce(p_input->>'description',''),auth.uid());mid:=i;
  result:=erp_membership_private.create_renewal(p_cafe,i,(p_input->>'customerId')::uuid,(p_input->>'packageId')::uuid,(p_input->>'invoiceDate')::date);
 ELSIF p_action IN('freeze','freeze_delete') THEN
  SELECT * INTO f FROM public.erp_membership_freezes WHERE cafe_id=p_cafe AND id=i FOR UPDATE;IF coalesce(f.revision,0)<>rev OR f.voided THEN RAISE EXCEPTION 'تغيرت فترة التوقف' USING ERRCODE='40001';END IF;
  mid:=CASE WHEN p_action='freeze' THEN(p_input->>'membershipId')::uuid ELSE f.membership_id END;SELECT * INTO m FROM public.erp_memberships WHERE cafe_id=p_cafe AND id=mid AND NOT deleted FOR UPDATE;IF m.id IS NULL THEN RAISE EXCEPTION 'العضوية غير متاحة';END IF;
  IF p_action='freeze_delete' THEN IF f.id IS NULL THEN RAISE EXCEPTION 'فترة التوقف غير موجودة';END IF;UPDATE public.erp_membership_freezes SET voided=true,revision=rev+1 WHERE cafe_id=p_cafe AND id=i;
  ELSE
   IF m.revision<>(p_input->>'membershipRevision')::integer OR(f.id IS NOT NULL AND f.membership_id<>mid) THEN RAISE EXCEPTION 'تغيرت العضوية' USING ERRCODE='40001';END IF;
   start_date:=(p_input->>'startsOn')::date;end_date:=(p_input->>'endsOn')::date;
   IF start_date IS NULL OR end_date IS NULL OR NOT isfinite(start_date) OR NOT isfinite(end_date) OR end_date<start_date OR end_date-start_date>365 OR jsonb_typeof(p_input->'extendMembership') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_input->'extendCredits') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع فترة التوقف وخيارات التمديد';END IF;
   SELECT * INTO r FROM public.erp_membership_renewals WHERE cafe_id=p_cafe AND membership_id=mid AND status='paid' AND starts_on<=start_date AND erp_membership_private.end_date(p_cafe,id)>=start_date ORDER BY starts_on DESC LIMIT 1;IF r.id IS NULL THEN RAISE EXCEPTION 'فترة التوقف يجب أن تبدأ ضمن اشتراك مدفوع';END IF;
   IF EXISTS(SELECT 1 FROM public.erp_membership_freezes WHERE cafe_id=p_cafe AND membership_id=mid AND id<>i AND NOT voided AND starts_on<=end_date AND ends_on>=start_date) THEN RAISE EXCEPTION 'فترة التوقف تتداخل مع فترة أخرى';END IF;
   IF EXISTS(SELECT 1 FROM public.erp_credit_allocations a JOIN public.erp_credit_usages u ON u.cafe_id=a.cafe_id AND u.id=a.usage_id JOIN public.erp_credit_charges ch ON ch.cafe_id=a.cafe_id AND ch.id=a.charge_id JOIN public.erp_membership_renewals rr ON rr.cafe_id=ch.cafe_id AND rr.id=ch.source_id WHERE a.cafe_id=p_cafe AND rr.membership_id=mid AND u.used_on BETWEEN start_date AND end_date) THEN RAISE EXCEPTION 'الفترة تتضمن استهلاكًا مسجلًا ولا يمكن إيقافها';END IF;
   INSERT INTO public.erp_membership_freezes VALUES(p_cafe,i,mid,r.id,start_date,end_date,(p_input->>'extendMembership')::boolean,(p_input->>'extendCredits')::boolean,false,rev+1) ON CONFLICT(cafe_id,id) DO UPDATE SET starts_on=excluded.starts_on,ends_on=excluded.ends_on,extend_membership=excluded.extend_membership,extend_credits=excluded.extend_credits,revision=excluded.revision;
  END IF;
  IF EXISTS(SELECT 1 FROM public.erp_credit_allocations a JOIN public.erp_credit_usages u ON u.cafe_id=a.cafe_id AND u.id=a.usage_id JOIN public.erp_credit_charges ch ON ch.cafe_id=a.cafe_id AND ch.id=a.charge_id JOIN public.erp_membership_renewals rr ON rr.cafe_id=ch.cafe_id AND rr.id=ch.source_id WHERE a.cafe_id=p_cafe AND rr.membership_id=mid AND u.used_on>erp_membership_private.end_date(p_cafe,rr.id,true)) THEN RAISE EXCEPTION 'التعديل يقصر رصيدًا استهلك بالفعل خلال فترة التمديد';END IF;
  UPDATE public.erp_memberships SET revision=revision+1 WHERE cafe_id=p_cafe AND id=mid;result:=jsonb_build_object('id',mid);
 ELSE
  SELECT * INTO m FROM public.erp_memberships WHERE cafe_id=p_cafe AND id=i AND NOT deleted FOR UPDATE;IF m.id IS NULL THEN RAISE EXCEPTION 'العضوية غير متاحة';END IF;IF m.revision<>rev THEN RAISE EXCEPTION 'تغيرت العضوية' USING ERRCODE='40001';END IF;mid:=i;
  IF p_action='renew' THEN
   IF EXISTS(SELECT 1 FROM public.erp_membership_renewals WHERE cafe_id=p_cafe AND membership_id=i AND status='pending') THEN RAISE EXCEPTION 'يوجد اشتراك بانتظار الإصدار أو السداد';END IF;
   result:=erp_membership_private.create_renewal(p_cafe,i,m.customer_id,(p_input->>'packageId')::uuid,(p_input->>'invoiceDate')::date);
  ELSIF p_action='edit' THEN UPDATE public.erp_memberships SET description=coalesce(p_input->>'description','') WHERE cafe_id=p_cafe AND id=i;
  ELSIF p_action='suspend' THEN UPDATE public.erp_memberships SET suspended=true WHERE cafe_id=p_cafe AND id=i;
  ELSIF p_action='resume' THEN UPDATE public.erp_memberships SET suspended=false WHERE cafe_id=p_cafe AND id=i;
  ELSIF p_action='delete' THEN UPDATE public.erp_memberships SET deleted=true,suspended=true WHERE cafe_id=p_cafe AND id=i;
  END IF;
  UPDATE public.erp_memberships SET revision=revision+1 WHERE cafe_id=p_cafe AND id=i;result:=coalesce(result,jsonb_build_object('id',i,'deleted',p_action='delete'));
 END IF;
 PERFORM erp_membership_private.sync(p_cafe);INSERT INTO public.erp_membership_events(cafe_id,membership_id,record_id,action,actor) VALUES(p_cafe,mid,i,p_action,auth.uid());INSERT INTO erp_membership_private.requests VALUES(p_cafe,p_request,auth.uid(),p_action,p_input,result);RETURN result;
END $$;
CREATE FUNCTION public.erp_customer_attendance_read(p_cafe uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE role text;BEGIN role:=erp_membership_private.authorize(p_cafe,'read','customer_attendance');PERFORM erp_membership_private.sync(p_cafe);RETURN jsonb_build_object(
 'records',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'number',a.number,'customerId',a.customer_id,'customerName',p.name,'attendedAt',a.attended_at,'staffName',coalesce(s.name,''),'voided',a.voided) ORDER BY a.attended_at DESC) FROM public.erp_customer_attendance a JOIN public.bf_parties p ON p.cafe_id=a.cafe_id AND p.id=a.customer_id LEFT JOIN public.bf_staff s ON s.cafe_id=a.cafe_id AND s.user_id=a.actor WHERE a.cafe_id=p_cafe),'[]'::jsonb),
 'customers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'phone',phone,'active',active,'eligible',erp_membership_private.attendance_allowed(p_cafe,id)) ORDER BY name) FROM public.bf_parties WHERE cafe_id=p_cafe AND kind='customer'),'[]'::jsonb),'policy',erp_membership_private.policy(p_cafe)->>'attendance','canCreate',role<>'auditor' AND erp_access_private.allowed(p_cafe,'customer_attendance','create'),'canDelete',role<>'auditor' AND erp_access_private.allowed(p_cafe,'customer_attendance','delete'));
END $$;
CREATE FUNCTION public.erp_customer_attendance_write(p_cafe uuid,p_action text,p_input jsonb,p_request uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
#variable_conflict use_variable
DECLARE id uuid;prior erp_membership_private.requests;r jsonb;BEGIN
 IF p_action NOT IN('checkin','delete') OR p_request IS NULL OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>500 THEN RAISE EXCEPTION 'الإجراء غير صالح';END IF;
 PERFORM erp_membership_private.authorize(p_cafe,CASE WHEN p_action='checkin' THEN 'create' ELSE 'delete' END,'customer_attendance');PERFORM erp_membership_private.sync(p_cafe);
 SELECT * INTO prior FROM erp_membership_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;IF FOUND THEN IF prior.actor<>auth.uid() OR prior.action<>'attendance_'||p_action OR prior.input<>p_input THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات أخرى';END IF;RETURN prior.result;END IF;
 IF p_action='checkin' THEN IF NOT erp_membership_private.attendance_allowed(p_cafe,(p_input->>'customerId')::uuid) THEN RAISE EXCEPTION 'لا تسمح سياسة العضويات بتسجيل حضور هذا العميل';END IF;id:=gen_random_uuid();INSERT INTO public.erp_customer_attendance(cafe_id,id,customer_id,actor) VALUES(p_cafe,id,(p_input->>'customerId')::uuid,auth.uid());
 ELSE id:=(p_input->>'id')::uuid;UPDATE public.erp_customer_attendance SET voided=true WHERE cafe_id=p_cafe AND erp_customer_attendance.id=id AND NOT voided;IF NOT FOUND THEN RAISE EXCEPTION 'سجل الحضور غير متاح';END IF;END IF;
 r:=jsonb_build_object('id',id);INSERT INTO public.erp_membership_events(cafe_id,record_id,action,actor) VALUES(p_cafe,id,'attendance_'||p_action,auth.uid());INSERT INTO erp_membership_private.requests VALUES(p_cafe,p_request,auth.uid(),'attendance_'||p_action,p_input,r);RETURN r;
END $$;
CREATE FUNCTION public.erp_credit_purchase(p_cafe uuid,p_customer uuid,p_package uuid,p_date date,p_request uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE prior erp_membership_private.requests;payload jsonb;r jsonb;BEGIN
 PERFORM erp_credit_private.authorize(p_cafe,'create');IF p_request IS NULL THEN RAISE EXCEPTION 'معرف العملية مطلوب';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,67951));
 payload:=jsonb_build_object('customer',p_customer,'package',p_package,'date',p_date);SELECT * INTO prior FROM erp_membership_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;IF FOUND THEN IF prior.actor<>auth.uid() OR prior.action<>'credit_purchase' OR prior.input<>payload THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات أخرى';END IF;RETURN prior.result;END IF;
 IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe AND id=p_customer AND kind='customer' AND active) THEN RAISE EXCEPTION 'العميل غير متاح';END IF;
 r:=erp_membership_private.create_renewal(p_cafe,NULL,p_customer,p_package,p_date);INSERT INTO public.erp_membership_events(cafe_id,record_id,action,actor) VALUES(p_cafe,(r->>'renewalId')::uuid,'credit_purchase',auth.uid());INSERT INTO erp_membership_private.requests VALUES(p_cafe,p_request,auth.uid(),'credit_purchase',payload,r);RETURN r;
END $$;
-- Refresh paid entitlement before reads/consumption and omit frozen dates from FEFO allocation.
DO $$DECLARE definition text;needle text:='AND NOT x.suspended AND x.starts_on<=d';BEGIN definition:=pg_get_functiondef('public.erp_credits_write(uuid,text,jsonb,uuid)'::regprocedure);IF position(needle IN definition)=0 THEN RAISE EXCEPTION 'Credit allocation source changed';END IF;definition:=replace(definition,needle,'AND NOT x.suspended AND erp_membership_private.charge_allowed(p_cafe,x.id,d) AND x.starts_on<=d');EXECUTE definition;END $$;
ALTER FUNCTION public.erp_credits_write(uuid,text,jsonb,uuid) RENAME TO erp_credits_write_before_memberships;
ALTER FUNCTION public.erp_credits_read(uuid) RENAME TO erp_credits_read_before_memberships;
REVOKE ALL ON FUNCTION public.erp_credits_write_before_memberships(uuid,text,jsonb,uuid),public.erp_credits_read_before_memberships(uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.erp_credits_read(p_cafe uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN PERFORM erp_credit_private.authorize(p_cafe);PERFORM erp_membership_private.sync(p_cafe);RETURN public.erp_credits_read_before_memberships(p_cafe)||jsonb_build_object('purchases',erp_membership_private.renewals_json(p_cafe,'credit'));END $$;
CREATE FUNCTION public.erp_credits_write(p_cafe uuid,p_action text,p_input jsonb,p_request uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN PERFORM erp_credit_private.authorize(p_cafe);PERFORM erp_membership_private.sync(p_cafe);RETURN public.erp_credits_write_before_memberships(p_cafe,p_action,p_input,p_request);END $$;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['erp_membership_settings','erp_memberships','erp_membership_renewals','erp_membership_freezes','erp_membership_events','erp_customer_attendance'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t);END LOOP;END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA erp_membership_private FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.erp_memberships_read(uuid),public.erp_memberships_write(uuid,text,jsonb,uuid),public.erp_customer_attendance_read(uuid),public.erp_customer_attendance_write(uuid,text,jsonb,uuid),public.erp_credit_purchase(uuid,uuid,uuid,date,uuid),public.erp_credits_read(uuid),public.erp_credits_write(uuid,text,jsonb,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.erp_memberships_read(uuid),public.erp_memberships_write(uuid,text,jsonb,uuid),public.erp_customer_attendance_read(uuid),public.erp_customer_attendance_write(uuid,text,jsonb,uuid),public.erp_credit_purchase(uuid,uuid,uuid,date,uuid),public.erp_credits_read(uuid),public.erp_credits_write(uuid,text,jsonb,uuid) TO authenticated;
COMMIT;
